import { createAuth } from "@aura-stack/auth"

export const auth = createAuth({
    oauth: [],
    basePath: "/api/auth",
    baseURL: "http://localhost:3000",
})

import { createAuthClient } from "@aura-stack/auth/client"

export const authClient = createAuthClient({
    basePath: "/api/auth",
    baseURL: "http://localhost:3000",
})
